"use client"

import React, { useCallback, useRef, useState } from "react"
import { ScrollShadow, cn } from "@heroui/react"
import { motion, type PanInfo } from "framer-motion"

/**
 * `DragScrollArea` — a vertical scroll region with a hidden scrollbar plus
 * Framer-Motion pointer pan (drag → `scrollTop`), so a hidden-bar region is
 * still scrollable on Windows. One region → plain `children`, no named slots.
 */

/** Props for {@link DragScrollArea}. */
export interface DragScrollAreaBaseProps {
    /** Scrollable content. */
    children: React.ReactNode
    /** Hide the native scrollbar (default true). */
    hideScrollBar?: boolean
    /** ScrollShadow edge fade size in px. */
    size?: number
    /** Extra classes on the scroll region. */
    className?: string
}

/**
 * Vertical scroll region with hidden scrollbar and Framer Motion pointer pan.
 *
 * Wheel/trackpad/touch scroll still work; `onPan` maps drag delta to `scrollTop`
 * so Windows users can scroll when the bar is hidden. Cursor is `grab` /
 * `grabbing` while panning. Presentational only.
 *
 * @param props - {@link DragScrollAreaBaseProps}
 */
const Base = ({
    className,
    children,
    hideScrollBar = true,
    size = 40,
}: DragScrollAreaBaseProps) => {
    const scrollRef = useRef<HTMLDivElement>(null)
    const [isPanning, setIsPanning] = useState(false)

    const onPan = useCallback((_event: PointerEvent, info: PanInfo) => {
        const element = scrollRef.current
        if (!element) {
            return
        }
        element.scrollTop -= info.delta.y
    }, [])

    return (
        <ScrollShadow
            ref={scrollRef}
            hideScrollBar={hideScrollBar}
            size={size}
            className={cn("overflow-y-auto", className)}
        >
            <motion.div
                className={cn(
                    "min-h-min select-none",
                    isPanning ? "cursor-grabbing" : "cursor-grab",
                )}
                onPanStart={() => setIsPanning(true)}
                onPan={onPan}
                onPanEnd={() => setIsPanning(false)}
            >
                {children}
            </motion.div>
        </ScrollShadow>
    )
}

/**
 * The pointer-pan scroll-region KHUNG namespace — one member:
 *
 * | Member | Content channel |
 * |---|---|
 * | `.Base` | `children` (one scrollable region) |
 */
export { Base as DragScrollArea }

"use client"

import React, {
    useCallback,
    useEffect,
    useRef,
    useState,
    type ReactNode,
} from "react"
import { cn } from "@heroui/react"

/**
 * `ResizableRail` — a side rail whose width the reader drags, persisted to `localStorage`.
 * One region (the rail body) → plain `children`, no named slots.
 */

/** Props for {@link ResizableRail}. */
export interface ResizableRailBaseProps {
    /** Rail content (e.g. the content-map tree). */
    children: ReactNode
    /** localStorage key the chosen width is persisted under. */
    storageKey: string
    /** Initial width in px before any persisted value loads. */
    defaultWidth?: number
    /** Smallest allowed width in px. */
    minWidth?: number
    /** Largest allowed width in px. */
    maxWidth?: number
    /** Accessible name for the drag handle (separator). */
    ariaLabel?: string
    /**
     * Which edge the drag handle sits on. `"right"` (default) suits a LEFT rail
     * (drag right = wider). `"left"` suits a RIGHT rail (handle on the inner edge,
     * drag left = wider) — e.g. a right-docked chat panel.
     */
    handleSide?: "left" | "right"
    /**
     * Publish the live width to this CSS custom property on `:root` (e.g.
     * `"--app-rail-w"`), resetting it to `0px` while unmounted. Lets
     * viewport-anchored `fixed` chrome dodge the rail via
     * `right-[var(--app-rail-w,0px)]`.
     */
    widthVar?: string
    /** Extra classes on the rail root. */
    className?: string
    /**
     * When `true`, each composed part emits `` so a
     * BlockAnatomy panel can badge it on-render. Off by default (production).
     */
}

/**
 * A side rail whose width the reader can drag to resize, with the chosen width
 * persisted to `localStorage`. A thin handle pinned to an edge is the splitter:
 * drag (pointer) or focus + Arrow keys to resize; the surrounding content
 * reflows. Tier-3 frame — owns the handle styling + the ephemeral width state;
 * the rail body arrives via `children`.
 *
 * Positioning (sticky / hidden-on-mobile / max-height) is supplied by the caller
 * through `className`; this frame only owns the width + the handle.
 *
 * @param props - {@link ResizableRailBaseProps}
 */
const Base = ({
    children,
    storageKey,
    defaultWidth = 320,
    minWidth = 256,
    maxWidth = 560,
    ariaLabel,
    handleSide = "right",
    widthVar,
    className,
}: ResizableRailBaseProps) => {
    // a left-edge handle widens when dragged LEFT (negative deltaX), so flip the sign.
    const dir = handleSide === "left" ? -1 : 1
    const [width, setWidth] = useState(defaultWidth)
    /** Latest width mirror so pointer-up can persist without a stale closure. */
    const widthRef = useRef(defaultWidth)
    /** Drag origin captured on pointer-down. */
    const dragRef = useRef<{ startX: number; startWidth: number } | null>(null)

    const clamp = useCallback(
        (value: number) => Math.min(Math.max(value, minWidth), maxWidth),
        [minWidth, maxWidth],
    )

    /** Commit a new width to state + the persistence ref. */
    const applyWidth = useCallback(
        (value: number) => {
            const next = clamp(value)
            widthRef.current = next
            setWidth(next)
        },
        [clamp],
    )

    // Hydrate the persisted width on mount (client-only; SSR/first paint uses
    // `defaultWidth` so markup matches and there is no hydration mismatch).
    useEffect(() => {
        const stored = window.localStorage.getItem(storageKey)
        if (stored === null) {
            return
        }
        const parsed = Number(stored)
        if (!Number.isNaN(parsed)) {
            applyWidth(parsed)
        }
    }, [storageKey, applyWidth])

    // Re-clamp when the BOUNDS move under us: a caller that narrows `maxWidth`
    // must snap the rail back on its own, without waiting for the next drag. The
    // persisted width is deliberately NOT overwritten — it is the reader's
    // PREFERENCE, and a temporarily small window must not clobber it.
    useEffect(() => {
        const bounded = clamp(widthRef.current)
        if (bounded !== widthRef.current) {
            widthRef.current = bounded
            setWidth(bounded)
        }
    }, [clamp])

    // Publish the live width so viewport-anchored `fixed` chrome can dodge the rail.
    // Reset to `0px` on unmount, NOT delete: consumers read it with a `0px` fallback.
    useEffect(() => {
        if (!widthVar) {
            return
        }
        const root = document.documentElement
        root.style.setProperty(widthVar, `${Math.round(width)}px`)
        return () => root.style.setProperty(widthVar, "0px")
    }, [widthVar, width])

    const onPointerDown = useCallback((event: React.PointerEvent<HTMLDivElement>) => {
        event.preventDefault()
        event.currentTarget.setPointerCapture(event.pointerId)
        dragRef.current = { startX: event.clientX, startWidth: widthRef.current }
        document.body.style.cursor = "col-resize"
        document.body.style.userSelect = "none"
    }, [])

    const onPointerMove = useCallback((event: React.PointerEvent<HTMLDivElement>) => {
        if (!dragRef.current) {
            return
        }
        applyWidth(dragRef.current.startWidth + dir * (event.clientX - dragRef.current.startX))
    }, [applyWidth, dir])

    const onPointerUp = useCallback((event: React.PointerEvent<HTMLDivElement>) => {
        if (!dragRef.current) {
            return
        }
        dragRef.current = null
        event.currentTarget.releasePointerCapture(event.pointerId)
        document.body.style.removeProperty("cursor")
        document.body.style.removeProperty("user-select")
        window.localStorage.setItem(storageKey, String(Math.round(widthRef.current)))
    }, [storageKey])

    const onKeyDown = useCallback((event: React.KeyboardEvent<HTMLDivElement>) => {
        const step = event.shiftKey ? 32 : 16
        if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") {
            return
        }
        event.preventDefault()
        applyWidth(widthRef.current + (event.key === "ArrowLeft" ? -step : step))
        window.localStorage.setItem(storageKey, String(Math.round(widthRef.current)))
    }, [applyWidth, storageKey])

    return (
        <div className={cn(className)} style={{ width }}>
            {children}
            {/* splitter: a thin line at the chosen edge that thickens to accent on hover/drag. */}
            <div
                role="separator"
                aria-orientation="vertical"
                aria-label={ariaLabel}
                tabIndex={0}
                onPointerDown={onPointerDown}
                onPointerMove={onPointerMove}
                onPointerUp={onPointerUp}
                onKeyDown={onKeyDown}
                className={cn(
                    "group absolute inset-y-0 z-20 flex w-3 cursor-col-resize items-stretch justify-center outline-none",
                    handleSide === "left" ? "left-0 -translate-x-1/2" : "right-0 translate-x-1/2",
                )}
            >
                <span className="h-full w-px bg-separator transition-colors group-hover:bg-accent group-focus-visible:bg-accent" />
            </div>
        </div>
    )
}

/**
 * The resizable side-rail KHUNG namespace — one member:
 *
 * | Member | Content channel |
 * |---|---|
 * | `.Base` | `children` (one rail body) |
 */
export { Base as ResizableRail }

"use client"

import React, { createContext, useContext, useEffect, useState } from "react"
import type { ReactNode } from "react"
import { motion, AnimatePresence, useReducedMotion } from "framer-motion"
import { cn } from "@heroui/react"
import { SidebarSimpleIcon } from "@phosphor-icons/react"
import { ButtonBase } from "@sb-components/atoms/buttons/Button/ButtonBase"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { DragScrollArea } from "@sb-components/behaviors/DragScrollArea/DragScrollArea"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `CollapsibleSidebar` — a content-agnostic shell for a left navigation sidebar
 * that collapses in place (no overlay/Drawer). Owns collapse/expand, the width
 * animation, persisting the choice to `localStorage`, and a `useSidebarCollapsed`
 * context so nav-row content can self-adapt to the icon-only rail. It never
 * inspects `children`. One leaf: `topSlot` presence and the collapsed flag are
 * data, so they are states, not separate leaves.
 */

/** Expanded panel width (full nav). */
const EXPANDED_WIDTH = "16rem"
/** Collapsed rail width — fits a centered icon row + the toggle. */
const COLLAPSED_WIDTH = "4rem"

/**
 * Named transition shapes (not inline object literals at the call site — check-inline-types
 * gate) for the width animation: a spring when motion is welcome, instant when the reader (or
 * their OS) asked for reduced motion.
 */
const SPRING_TRANSITION = { type: "spring" as const, stiffness: 420, damping: 38 }
const INSTANT_TRANSITION = { duration: 0 }
/** Title fade — quick cross-fade, same instant fallback under reduced motion. */
const FADE_TRANSITION = { duration: 0.15 }

/**
 * Collapsed flag shared with nav-row children so a row can drop to icon-only in
 * the rail. Internal UI chrome state — not an app store.
 */
const SidebarCollapsedContext = createContext(false)

/** Read whether the surrounding {@link CollapsibleSidebar} is collapsed (icon-rail). */
export const useSidebarCollapsed = (): boolean => useContext(SidebarCollapsedContext)

/** Props for the {@link CollapsibleSidebar} composite. */
export interface CollapsibleSidebarProps {
    /** Heading shown in the panel header (hidden while collapsed). */
    title: string
    /** Accessible label for the collapse toggle (expanded state). */
    collapseLabel: string
    /** Accessible label for the expand toggle (collapsed state). */
    expandLabel: string
    /**
     * Stable key under which the collapsed flag persists in `localStorage`, so
     * the choice survives navigation between pages that share this sidebar.
     */
    storageKey: string
    /**
     * Optional node pinned BETWEEN the header and the scrollable nav — always
     * visible (outside the scroll area). Rendered inside the collapsed-context
     * provider, so it can adapt to the rail (e.g. a resume pill → play icon).
     */
    topSlot?: ReactNode
    /** The panel body — nav rows/groups; content-agnostic, this shell never inspects them. */
    children: ReactNode
}

/**
 * A left navigation sidebar that collapses IN PLACE: the panel animates between
 * a full {@link EXPANDED_WIDTH} (title + nav) and a thin {@link COLLAPSED_WIDTH}
 * rail (just the toggle), and the surrounding content reflows beside it — no
 * overlay/Drawer. Self-contained: the collapsed state is local UI chrome,
 * hydrated from storage on mount (SSR-safe — starts expanded, then syncs).
 *
 * @param props - {@link CollapsibleSidebarProps}
 */
export const CollapsibleSidebar = ({
    title,
    collapseLabel,
    expandLabel,
    storageKey,
    topSlot,
    children,
}: CollapsibleSidebarProps) => {
    const reduceMotion = useReducedMotion()
    const [collapsed, setCollapsed] = useState(false)

    // hydrate the persisted choice after mount (avoids SSR/client mismatch)
    useEffect(() => {
        const stored = window.localStorage.getItem(storageKey)
        if (stored !== null) {
            setCollapsed(stored === "true")
        }
    }, [storageKey])

    /** Flip + persist the collapsed flag. */
    const toggle = () => {
        setCollapsed((prev) => {
            const next = !prev
            window.localStorage.setItem(storageKey, String(next))
            return next
        })
    }

    // §10a: the vertical rhythm between header / topSlot / nav is owned by THIS
    // StackV's gap — no section carries its own margin (a prior draft put
    // `mb-6` on the header row itself, flagged by check-padding as a second
    // owner for the same seam).
    return (
        <SidebarCollapsedContext.Provider value={collapsed}>
            <motion.aside

                initial={false}
                animate={{ width: collapsed ? COLLAPSED_WIDTH : EXPANDED_WIDTH }}
                transition={reduceMotion ? INSTANT_TRANSITION : SPRING_TRANSITION}
                className={cn(
                    // ONE padding wrapper for the whole rail: p-6 expanded / px-3 py-6
                    // collapsed. No frame in this tree types an asymmetric inset, so this
                    // stays hand-written on the composite's own bespoke root (§13c precedent:
                    // Toolbar/ModalShell/DrawerShell do the same on theirs).
                    "flex h-full shrink-0 overflow-hidden border-r border-default",
                    collapsed ? "px-3 py-6" : "p-6",
                )}
            >
                <StackV
                    gap={6}
                    classNames={["min-h-0", "flex-1"]}
                    items={[
                        () => (
                            <StackH
                                gap={3}
                                principle="flex-action"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                justify={collapsed ? "center" : "between"}
                                items={[
                                    () => (
                                        <AnimatePresence initial={false}>
                                            {!collapsed ? (
                                                <motion.div
                                                    key="title"
                                                    initial={{ opacity: 0 }}
                                                    animate={{ opacity: 1 }}
                                                    exit={{ opacity: 0 }}
                                                    transition={reduceMotion ? INSTANT_TRANSITION : FADE_TRANSITION}
                                                    className="min-w-0"
                                                >
                                                    <Typography
                                                        size="h5"
                                                        weight="bold"
                                                        truncate
                                                        text={title}
                                                    />
                                                </motion.div>
                                            ) : null}
                                        </AnimatePresence>
                                    ),
                                    () => (
                                        <ButtonBase
                                            isIconOnly
                                            variant="ghost"
                                            size="sm"
                                            ariaLabel={collapsed ? expandLabel : collapseLabel}
                                            prefixIcon={SidebarSimpleIcon}
                                            onPress={toggle}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        // pinned top slot (e.g. resume pill) — above the scroll area, always
                        // visible. min-w-0: a column-flex item defaults to content-width
                        // (min-width: auto), which would let it overflow the rail and get
                        // hard-clipped by overflow-hidden instead of shrinking so its own
                        // `truncate` text can ellipsize.
                        () => (
                            <div className="min-w-0">
                                {topSlot}
                            </div>
                        ),
                        // body: the nav — ALWAYS rendered; row content decides its own icon-only
                        // look off `useSidebarCollapsed`. `DragScrollArea` owns the overflow
                        // (hidden scrollbar + Windows-safe pointer-pan); `StackV` gives the
                        // column its `gap={4}` rhythm and default `align="stretch"` (rows
                        // fill the rail's width whether expanded or collapsed), since the scroll
                        // frame itself lays out nothing.
                        () => (
                            <nav className="flex min-h-0 flex-1 flex-col">
                                <DragScrollArea size={40} className="flex-1">
                                    <StackV gap={4} items={[() => children]} />
                                </DragScrollArea>
                            </nav>
                        ),
                    ]}
                />
            </motion.aside>
        </SidebarCollapsedContext.Provider>
    )
}

import React from "react"
import { Tabs as HeroTabs } from "@heroui/react"
import {
    CodeIcon,
    FileTextIcon,
    HouseIcon,
    PulseIcon,
    PuzzlePieceIcon,
    RocketIcon,
} from "@phosphor-icons/react"
import { TabsExtended } from "@sb-components/atoms/navigation/Tabs/Tabs"
import type { IconComponent } from "@sb-components/atoms/navigation/Tabs/Tabs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * `ProfileTabsBar` — the public-profile route strip (overview / projects /
 * challenges / skills / cv / activity). Draws the already-gated tab list the
 * caller hands it and reports a pick back via `onTabChange`; visibility gating
 * stays upstream. Uses `TabsExtended` (composing the `Tabs.*` children
 * directly) so one region (icon) can stay visible while another (label + owner
 * marker) drops below `@app-md`. One leaf: which tabs show, which is active,
 * and which carries the "· hidden" marker are data.
 */

/** Every public-profile destination this strip can offer — ported from the real `ProfileTab`. */
export type ProfileTab = "overview" | "projects" | "challenges" | "skills" | "cv" | "activity"

/** Tab → label. Block-owned wording (§14d.1), ported verbatim from `publicProfile.tabs.*`. */
const TAB_LABEL: Record<ProfileTab, string> = {
    overview: "Overview",
    projects: "Projects",
    challenges: "Challenges",
    skills: "Skills",
    cv: "CV",
    activity: "Activity",
}

/** Tab → icon. Ported 1:1 from the real `TAB_ICONS` table. */
const TAB_ICON: Record<ProfileTab, IconComponent> = {
    overview: HouseIcon,
    projects: RocketIcon,
    challenges: PuzzlePieceIcon,
    skills: CodeIcon,
    cv: FileTextIcon,
    activity: PulseIcon,
}

/**
 * Glyph scale for a `text-sm` (14px) label — same §5a pairing `TabsBase` already
 * uses for its own icon column, ported here since this block hand-composes the
 * tab's inside instead of going through that atom's `items`.
 */
const TAB_ICON_CLASS = "size-3.5"
const TAB_ICON_WEIGHT = "bold" as const

/** The owner-only marker riding beside a hidden section tab's label. */
const HIDDEN_MARKER = "· hidden"

/** Props for {@link ProfileTabsBar}. */
export interface ProfileTabsBarProps {
    /** Which destination's route is being viewed now. */
    activeTab: ProfileTab
    /**
     * Destinations to render, in display order — ALREADY gated by the caller
     * (owner sees every tab; a visitor never receives a tab their
     * `sectionVisibility`/`hasPublicCv` withheld). This block draws exactly this
     * list, nothing more.
     */
    visibleTabs: ReadonlyArray<ProfileTab>
    /** Fired with the tab the visitor picked. The screen decides how to navigate. */
    onTabChange: (tab: ProfileTab) => void
    /**
     * Section tabs (a subset of {@link visibleTabs}) the OWNER has switched off
     * for other visitors — rendered with a "· hidden" marker beside the label so the
     * owner can tell at a glance. Omit (or leave empty) for a visitor's own view.
     */
    hiddenTabs?: ReadonlyArray<ProfileTab>
    /** Accessible name for the tab list, localized by the caller (blocks carry no i18n). */
    ariaLabel: string
}

/**
 * The profile's route-derived tab strip. See the file header for why the gating
 * computation and routing stay out of this block, and why `TabsExtended` (not
 * `TabsBase`) composes it.
 *
 * @param props - {@link ProfileTabsBarProps}
 */
const ProfileTabsBar = ({
    activeTab,
    visibleTabs,
    onTabChange,
    hiddenTabs,
    ariaLabel,
}: ProfileTabsBarProps) => {
    return (
        <div className="w-full">
            <TabsExtended
                selectedKey={activeTab}
                onSelectionChange={(key) => onTabChange(key as ProfileTab)}


            >
                <HeroTabs.ListContainer>
                    <HeroTabs.List aria-label={ariaLabel}>
                        {visibleTabs.map((tabId) => {
                            const Icon = TAB_ICON[tabId]
                            const isHidden = hiddenTabs?.includes(tabId) ?? false
                            return (
                                <HeroTabs.Tab
                                    key={tabId}
                                    id={tabId}

                                >
                                    <StackH
                                        gap={2}
                                        principle="icon-text"
                                        explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                        align="center"

                                        items={[
                                            () => <Icon aria-hidden focusable="false" className={TAB_ICON_CLASS} weight={TAB_ICON_WEIGHT} />,
                                            // Icon-only below @app-md — label (and its marker) only
                                            // from a tablet-wide profile strip up.
                                            () => (
                                                <span className="hidden @app-md:inline">
                                                    <Typography size="sm" text={TAB_LABEL[tabId]} />
                                                    {isHidden ? (
                                                        <>
                                                            {" "}
                                                            <Typography size="sm" color="muted" text={HIDDEN_MARKER} />
                                                        </>
                                                    ) : null}
                                                </span>
                                            ),
                                        ]}
                                    />
                                    <HeroTabs.Indicator />
                                </HeroTabs.Tab>
                            )
                        })}
                    </HeroTabs.List>
                </HeroTabs.ListContainer>
            </TabsExtended>
        </div>
    )
}

export { ProfileTabsBar }

import React from "react"
import { cn, Skeleton as HeroSkeleton } from "@heroui/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { LinkBack } from "@sb-components/atoms/navigation/Link/Link"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { principleAttr } from "@sb-components/frames/_principles"

/**
 * `WorkSessionHeader` — the band that signals "you are inside a session",
 * shared across quiz, flashcard review, and mock interview. Knows what a
 * session is: a length, a position, steps that can be graded, and two distinct
 * exits — a back link that leaves and keeps the run resumable, and a finish
 * button that ends it and goes to results. "Done" (graded, filled) and
 * "current" (viewing, a taller bar) are independent signals. Takes typed data
 * (counter string, optional time-left string), no `ReactNode` slot. Leaf by
 * structure: losing the finish control or the rail's interactivity changes the
 * shape; position and which steps are graded are states.
 */

/** Props {@link WorkSessionHeader} carries regardless of loading state. */
interface WorkSessionHeaderOwnProps {
    /** Back-link label, localized by the caller — means LEAVE, run stays resumable. */
    backLabel: string
    /** Fired when the learner leaves without ending the run. */
    onBack: () => void
    /** What the session is, e.g. "Quick quiz". */
    title?: string
    /** Optional time remaining, e.g. "2:14". Omitted → the session is untimed. */
    timeLeft?: string
    /** Steps already graded, 1-based. Rendered FILLED, independently of `current`. */
    doneSteps?: Array<number>
    /** Fired with a 1-based step when the learner taps the rail. Omitted → the rail is inert. */
    onStepPress?: (step: number) => void
    /** Finish-label, localized. Present with `onFinish` → the end-now control shows. */
    finishLabel?: string
    /** Fired when the learner ends the run and goes to the results. */
    onFinish?: () => void
}

/**
 * Props for {@link WorkSessionHeader}. `counter`/`total`/`current` are
 * REQUIRED unless `isSkeleton` (§12b) — the run's own length/position isn't
 * known before the session data arrives.
 */
export type WorkSessionHeaderProps = WorkSessionHeaderOwnProps &
    (
        | { isSkeleton: true; counter?: string; total?: number; current?: number }
        | {
            isSkeleton?: false
            /** Where the learner is, already worded by the caller, e.g. "Question 3 / 10". */
            counter: string
            /** How many steps the session has. Drives the rail's segment count. */
            total: number
            /** Which step is being VIEWED, 1-based. Rendered as a TALLER segment. */
            current: number
        }
    )

/**
 * Session band with a progress rail. See the file header for the full contract.
 *
 * @param props - {@link WorkSessionHeaderProps}
 */
const WorkSessionHeader = ({
    backLabel,
    onBack,
    title,
    counter,
    timeLeft,
    total,
    current,
    doneSteps,
    onStepPress,
    finishLabel,
    onFinish,
    isSkeleton = false,
}: WorkSessionHeaderProps) => {
    if (isSkeleton) {
        return (
            <div className="border-b border-default bg-surface">
                <StackH
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    isSkeleton={isSkeleton}
                    items={[
                        () => <HeroSkeleton className="h-4 w-16 rounded" />,
                        () => <HeroSkeleton className="h-4 w-24 rounded" />,
                        () => <span className="flex-1" />,
                    ]}
                />
                {/* `cell-pad` is the closest registered padding token to this wrapper's
                    `p-2` — the frame's `padding={3}` keeps the exact 8px inset. */}
                <StackV
                    principle="cell-pad"
                    explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
                    isSkeleton={isSkeleton}
                    items={[() => <HeroSkeleton className="h-1 w-full rounded-full" />]}
                />
            </div>
        )
    }
    const done = new Set(doneSteps ?? [])

    // `total` is REQUIRED whenever `isSkeleton` is false (discriminated union
    // above) — already guaranteed by the early return at `isSkeleton`; the
    // `?? 0` only satisfies narrowing across the destructure, never actually fires.
    const railSegments = Array.from({ length: total ?? 0 }, (_, index) => {
        const step = index + 1
        const isDone = done.has(step)
        const isCurrent = step === current
        const segment = (
            <span
                className={cn(
                    "block w-full rounded-full",
                    // TALLER means VIEWING; FILLED means GRADED. Two signals, and
                    // neither is allowed to overwrite the other.
                    isCurrent ? "h-1.5" : "h-1",
                    isDone ? "bg-success" : "bg-default",
                )}
            />
        )
        // `py-2` enlarges the tap target around the thin 4px bar; `control-pad` is the
        // closest registered token (its own `py-2`) — this leaf carries no matching `px`
        // since the segment already fills `flex-1` width.
        return onStepPress != null ? (
            <button
                key={step}
                type="button"
                aria-label={`${counter} — ${step}`}
                className="flex-1 py-2" data-principle={principleAttr("control-pad")}
                onClick={() => onStepPress(step)}
            >
                {segment}
            </button>
        ) : (
            <span key={step} className="flex-1 py-2" data-principle={principleAttr("control-pad")}>{segment}</span>
        )
    })

    return (
        <div className="border-b border-default bg-surface">
            <StackH
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                isSkeleton={isSkeleton}
                items={[
                    () => <LinkBack label={backLabel} onPress={onBack} />,
                    ...(title != null ? [() => <Typography size="sm" weight="bold" text={title} />] : []),
                    () => <Typography size="sm" color="muted" text={counter} />,
                    ...(timeLeft != null
                        ? [() => <Typography size="sm" weight="medium" text={timeLeft} tabularNums />]
                        : []),
                    () => <span className="flex-1" />,
                    ...(onFinish != null && finishLabel != null
                        ? [
                            // "END IT NOW" (line 20) is an
                            // action that ends the session mid-way — uses `danger-soft`.
                            () => <Button label={finishLabel} variant="danger-soft" size="sm" onPress={onFinish} />,
                        ]
                        : []),
                ]}
            />
            {/* The rail. Segments are laid out by a frame so the seam stays on scale; each
                segment carries its own hit zone, because a 4px bar is not a touch target. */}
            <StackH
                principle="chip-row"
                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                isSkeleton={isSkeleton}
                items={[() => railSegments]}
            />
        </div>
    )
}

