    /**
     * Plain-text mode: render authored content with INLINE markdown decoration
     * stripped to raw text (inline code, bold, italic, links) while keeping block
     * structure + `:::muted` arc labels + cloze. Opt-in for flashcard + mock-interview
     * surfaces; lesson/challenge content keeps full markdown.
     */
    plain?: boolean
    /**
     * Render fenced code blocks as RAISED cards (`bg-surface` + shadow) rather
     * than the default recessed wells (`bg-background`). Opt-in for surfaces that
     * render markdown on the bare page CANVAS (e.g. the Playground left pane).
     */
    codeElevated?: boolean
}

/**
 * Renders markdown with GFM and shared typography aligned with the app theme —
 * the CONNECTED half: reads the active theme/translator and memoizes the
 * element-renderer map (see {@link buildMarkdownRenderers}). See
 * `design/storybook/architecture/split.md`.
 * @param props - {@link MarkdownContentConnectedProps}
 */
export const MarkdownContent = ({ markdown, reading = false, arcSections = false, plain = false, codeElevated = false, className }: MarkdownContentConnectedProps) => {
    const theme = useTheme()
    const t = useTranslations()
    // hold back an unterminated trailing mermaid fence FIRST (same rule the
    // presentational half applies) so the caption scan never reads a mid-fence
    // partial diagram as an already-closed one.
    const stableMarkdown = useMemo(() => holdBackIncompleteMermaidFence(markdown), [markdown])
    const mermaidCaptions = useMemo(() => extractMermaidCaptions(stableMarkdown), [stableMarkdown])
    const components = useMemo(
        () => buildMarkdownRenderers({
            isDark: theme.theme === "dark",
            t,
            mermaidCaptions,
            reading,
            plain,
            codeElevated,
        }),
        [
            theme.theme,
            t,
            mermaidCaptions,
            reading,
            plain,
            codeElevated,
        ],
    )
    return (
        <_MarkdownContent
            markdown={markdown}
            reading={reading}
            arcSections={arcSections}
            components={components}
            className={className}
        />
    )
}

"use client"

import React, {
    useCallback,
} from "react"
import type {
    ReactNode,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import type { ResponsiveBreadcrumbItem } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { pathConfig } from "@/resources/path"

/** Props for {@link SettingsBreadcrumb}. */
export interface SettingsBreadcrumbProps {
    /** The current page label — the last, read-only crumb. */
    current: ReactNode
}

/**
 * Shared settings/profile breadcrumb trail: `Home › Profile › Settings › <current>`
 * (the last crumb is read-only). DRY-replaces the hand-rolled trail every settings
 * page used to repeat, so every page under `/profile/settings/*` shows the same
 * tier-1 breadcrumb. Mirrors the trail the edit/security pages already build.
 *
 * @param props - {@link SettingsBreadcrumbProps}
 */
export const SettingsBreadcrumb = ({
    current,
}: SettingsBreadcrumbProps) => {
    const t = useTranslations()
    const router = useRouter()
    const locale = useLocale()

    /** Navigate to the home page (breadcrumb root). */
    const onNavigateHome = useCallback(
        () => router.push(pathConfig().locale().build()),
        [
            router,
        ],
    )
    /** Navigate to the profile (breadcrumb parent). */
    const onNavigateProfile = useCallback(
        () => router.push(pathConfig().locale(locale).profile().build()),
        [
            router,
            locale,
        ],
    )
    /** Navigate to the settings root (breadcrumb parent of every settings page). */
    const onNavigateSettings = useCallback(
        () => router.push(pathConfig().locale(locale).profile().settings().build()),
        [
            router,
            locale,
        ],
    )

    const items: Array<ResponsiveBreadcrumbItem> = [
        { key: "home", label: t("nav.home"), onPress: onNavigateHome },
        { key: "profile", label: t("nav.profile"), onPress: onNavigateProfile },
        { key: "settings", label: t("nav.settings"), onPress: onNavigateSettings },
        { key: "current", label: current },
    ]

    return <ResponsiveBreadcrumb items={items} />
}
